  'dashboard-tecnico': { titulo: 'Dashboard Técnico', que: 'Resumen del frente del ingeniero: sus partidas, avance y pendientes.', como: ['Es tu página de arranque: de acá saltás a reportar avance o pedir insumos.'] },
